using System;using System.Collections.Generic;using System.IO;using System.Threading;using System.Threading.Tasks;
namespace QQImageSwitch
{
    static class QrAiSchemeTests
    {
        static int checks;static void Require(bool value,string message){checks++;if(!value)throw new Exception("AI schemes: "+message);}
        static void Put(string path){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,"fixture");}
        static bool Reject(Action action){try{action();return false;}catch(ArgumentException){return true;}catch(InvalidOperationException){return true;}}
        public static void Run(string output)
        {
            checks=0;string root=Path.Combine(output,"ai-scheme-tests");Directory.CreateDirectory(root);string settings=Path.Combine(root,"settings.json"),model15=Path.Combine(root,"base","dreamshaper-8"),modelXL=Path.Combine(root,"base","sdxl-base");QrAiDirectoryProfileTests.CreateBase(model15,false);QrAiDirectoryProfileTests.CreateBase(modelXL,true);
            var initial=new QrAiOptions{Root=root};Require(QrAiService.RecommendedScheme(initial)&&QrAiService.ProfileFor(initial).Id=="dreamshaper-8","first-run recommendation not paired with default prompt");initial.Family="sdxl";initial.Base=modelXL;initial.Environment="cpu";initial.Profiles[model15]=new QrAiGenerationProfile{Family="sd15",Id="custom",PromptTemplate="{prompt}",NegativeTemplate="{negative}"};QrAiService.UseRecommendedScheme(initial);Require(initial.Family=="sd15"&&initial.Environment=="cuda"&&initial.Base==null&&initial.Control==null&&QrAiService.RecommendedScheme(initial)&&!initial.Profiles.ContainsKey(model15),"reset did not restore recommended resources/profile");Require(initial.Selections["sdxl"].Base==modelXL&&initial.Selections["sdxl"].Environment=="cpu"&&Directory.Exists(modelXL),"reset deleted or forgot standby models");initial.Base=model15;initial.Control=Path.Combine(root,"controlnet","qr-monster-sd15");Require(QrAiService.RecommendedScheme(initial),"resolved default models mislabeled as standby");initial.Environment="cpu";Require(!QrAiService.RecommendedScheme(initial),"standby runtime mislabeled recommended");
            var options=new QrAiOptions{Root=root,AutoRoot=false,Base=model15,Environment="cpu"};options.Profiles[model15]=new QrAiGenerationProfile{Family="sd15",Id="custom",PromptTemplate="material, {prompt}",NegativeTemplate="{negative}, flat sticker",Steps=32,Guidance=5.5,Strength=.4,ClipSkip=1};QrAiService.SaveOptions(options,settings);
            options.Family="sdxl";options.Base=modelXL;options.Environment="cuda";QrAiService.SaveOptions(options,settings);var saved=QrAiService.LoadOptions(settings);
            Require(saved.Family=="sdxl"&&saved.Environment=="cuda"&&saved.Base==modelXL,"current family/runtime not saved");Require(saved.Selections["sd15"].Base==model15&&saved.Selections["sd15"].Environment=="cpu","previous family selection lost");Require(saved.Profiles[model15].PromptTemplate=="material, {prompt}"&&saved.Profiles[model15].Steps==32,"per-model profile lost");Require(QrAiService.ProfileFor(saved).Id=="sdxl-base-1.0","XL default paired profile incorrect");options.Profiles.Remove(model15);options.Family="sd15";options.Base=model15;Require(QrAiService.ProfileFor(options).Id=="dreamshaper-8","SD15 default paired profile incorrect");
            var clone=QrAiService.CopyOptions(saved);clone.Profiles[model15].PromptTemplate="{prompt}";Require(saved.Profiles[model15].PromptTemplate!="{prompt}","cancelled dialog shares profile objects");
            File.WriteAllText(settings,Inspection.Json().Serialize(new{Root=root,Base=modelXL,Control=""}));saved=QrAiService.LoadOptions(settings);Require(saved.Family=="sdxl"&&saved.Environment=="cuda","legacy XL selection migrated as SD15");
            File.WriteAllText(settings,Inspection.Json().Serialize(new{Root=root,Family="sdxl",Environment="../../outside",Selections=new Dictionary<string,object>{{"sdxl",null}},Profiles=new Dictionary<string,object>{{modelXL,new{Family="sdxl",Id="custom",PromptTemplate="{prompt}",NegativeTemplate="{negative}",Guidance=1e100}},{model15,null}}}));saved=QrAiService.LoadOptions(settings);Require(saved.Environment=="cuda"&&saved.Profiles.Count==0&&saved.Selections.Count==0,"damaged null/huge profile settings crash or escape runtime");
            Require(QrAiService.RuntimeFolder(root,"cpu")==Path.Combine(root,"runtime","cpu")&&QrAiService.Python(root,"cpu")!=QrAiService.Python(root),"environments share their Python installation");Require(Reject(()=>QrAiService.RuntimeFolder(root,"../escape")),"unsafe runtime identifier accepted");
            options=new QrAiOptions{Root=root,Family="sd15",Base=modelXL};Require(Reject(()=>QrAiService.ValidateScheme(options)),"wrong-family base accepted");options.Family="sdxl";options.Control=QrAiIntegrityTests.Model("scheme-sd15-control",768,false,false,true);Require(Reject(()=>QrAiService.ValidateScheme(options)),"wrong-family ControlNet accepted");options.Control=null;QrAiService.ValidateScheme(options);checks++;
            foreach(var profile in new[]{new QrAiGenerationProfile{Family="sdxl",Id="custom",PromptTemplate="{prompt}",NegativeTemplate="{negative}",ClipSkip=1},new QrAiGenerationProfile{Family="sdxl",Id="custom",PromptTemplate="guess",NegativeTemplate="{negative}"},new QrAiGenerationProfile{Family="sdxl",Id="sd15-standard"}})Require(Reject(()=>profile.Validate("sdxl")),"invalid prompt/parameter profile accepted");
            string managed=Path.Combine(root,"managed"),cpu=Path.Combine(managed,"runtime","cpu","python","owned.txt"),cuda=Path.Combine(managed,"runtime","python","owned.txt"),unknown=Path.Combine(managed,"user-picture.png");QrAiService.Materialize(managed);QrAiStorage.RegisterEnvironment(managed,"cpu");Put(cpu);Put(cuda);Put(unknown);var plan=QrAiStorage.PlanAll(managed);QrAiStorage.Execute(plan,null,CancellationToken.None).GetAwaiter().GetResult();Require(!File.Exists(cpu)&&!File.Exists(cuda)&&File.Exists(unknown),"managed CPU/CUDA cleanup escaped ownership");
            string preexisting=Path.Combine(root,"preexisting"),keep=Path.Combine(preexisting,"runtime","cpu","keep.txt");Put(keep);QrAiStorage.RegisterEnvironment(preexisting,"cpu");QrAiStorage.Execute(QrAiStorage.PlanAll(preexisting),null,CancellationToken.None).GetAwaiter().GetResult();Require(File.Exists(keep),"preexisting unowned CPU directory was deleted");
            string python=Environment.GetEnvironmentVariable("AIPT_TEST_PYTHON");if(!string.IsNullOrEmpty(python)&&File.Exists(python))
            {
                string engine=Path.Combine(root,"routing","engine"),worker=Path.Combine(engine,"probe.py");Directory.CreateDirectory(engine);File.WriteAllText(worker,"import os,json\nprint(json.dumps({'event':'result','temp':os.environ['TEMP'],'cache':os.environ['PIP_CACHE_DIR']}))\n");
                foreach(string environment in new[]{"cpu","cuda"}){var result=Task.Run(()=>QrAiService.Run(python,worker,new Dictionary<string,object>{{"operation","probe"},{"environment",environment}},s=>{},null,CancellationToken.None)).GetAwaiter().GetResult();string expected=QrAiService.RuntimeFolder(Path.GetDirectoryName(engine),environment);Require((string)result["temp"]==Path.Combine(expected,"temp")&&(string)result["cache"]==Path.Combine(expected,"pip-cache"),"private inference caches crossed environments");}
            }
            File.WriteAllText(Path.Combine(root,"PASS.md"),"PASS: "+checks+" checks; model/runtime/profile persistence and migration, family mismatch, malformed settings, CPU/CUDA cache routing, managed cleanup and external ownership.");
        }
    }
}
